import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoDatabase;
import com.mongodb.client.model.Filters;
import org.bson.Document;
import org.bson.conversions.Bson;
import javax.servlet.http.HttpServletRequest;
import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class DocumentSearchService {

    private final MongoDatabase database;
    private final QueryCache queryCache;
    private static final Pattern SAFE_FIELD = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_.]{0,63}$");
    private static final Set<String> BLOCKED_OPERATORS = Set.of(
        "$where", "$expr", "$function", "$accumulator");

    public DocumentSearchService(MongoDatabase database) {
        this.database = database;
        this.queryCache = new QueryCache(256);
    }

    // Main search endpoint
    public List<Document> search(String collection, Map<String, Object> criteria,
                                  String callerRole, int page, int pageSize) {
        validatePagination(page, pageSize);
        MongoCollection<Document> coll = database.getCollection(sanitizeCollectionName(collection));

        Document query = buildQuery(criteria, callerRole);
        Document projection = buildProjection(callerRole);

        return coll.find(query)
                   .projection(projection)
                   .skip(page * pageSize)
                   .limit(pageSize)
                   .into(new ArrayList<>());
    }

    private Document buildQuery(Map<String, Object> criteria, String callerRole) {
        Document query = new Document();

        for (Map.Entry<String, Object> entry : criteria.entrySet()) {
            String field = entry.getKey();
            Object value = entry.getValue();

            if (!SAFE_FIELD.matcher(field).matches()) {
                throw new IllegalArgumentException("Invalid field name: " + field);
            }

            Object sanitized = sanitizeValue(value, 0);
            query.append(field, sanitized);
        }

        // Apply role-based visibility filter
        if (!"admin".equals(callerRole)) {
            query.append("visibility", "public");
        }

        return query;
    }

    // Overloaded sanitizeValue for different depths
    private Object sanitizeValue(Object value, int depth) {
        if (depth > 3) {
            throw new IllegalArgumentException("Query too deeply nested");
        }

        if (value == null) {
            return null;
        }

        if (value instanceof String) {
            return sanitizeStringValue((String) value);
        }

        if (value instanceof Number || value instanceof Boolean) {
            return value;
        }

        if (value instanceof List) {
            return sanitizeList((List<?>) value, depth);
        }

        if (value instanceof Map) {
            return sanitizeMap((Map<?, ?>) value, depth);
        }

        throw new IllegalArgumentException("Unsupported value type: " + value.getClass());
    }

    private String sanitizeStringValue(String value) {
        if (value.length() > 1000) {
            throw new IllegalArgumentException("String value too long");
        }
        // Block operator-like strings
        if (value.startsWith("$")) {
            throw new IllegalArgumentException("Invalid string value");
        }
        return value;
    }

    private List<Object> sanitizeList(List<?> list, int depth) {
        if (list.size() > 50) {
            throw new IllegalArgumentException("List too large");
        }
        // For $in queries, allow a list of scalar values
        List<Object> result = new ArrayList<>();
        for (Object item : list) {
            if (item instanceof String || item instanceof Number || item instanceof Boolean) {
                result.add(sanitizeValue(item, depth + 1));
            } else {
                throw new IllegalArgumentException("List items must be scalar");
            }
        }
        return result;
    }

    @SuppressWarnings("unchecked")
    private Document sanitizeMap(Map<?, ?> map, int depth) {
        Document doc = new Document();
        Set<String> allowedOperators = Set.of("$eq", "$gt", "$gte", "$lt", "$lte",
                                               "$in", "$nin", "$ne", "$exists", "$regex");

        for (Map.Entry<?, ?> entry : map.entrySet()) {
            String key = entry.getKey().toString();
            Object val = entry.getValue();

            if (key.startsWith("$")) {
                if (BLOCKED_OPERATORS.contains(key)) {
                    throw new IllegalArgumentException("Operator not allowed: " + key);
                }
                if (!allowedOperators.contains(key)) {
                    throw new IllegalArgumentException("Unknown operator: " + key);
                }
                // Validate operator values
                if ("$regex".equals(key)) {
                    val = sanitizeRegex(val);
                } else if ("$in".equals(key) || "$nin".equals(key)) {
                    if (!(val instanceof List)) {
                        throw new IllegalArgumentException("$in/$nin require array value");
                    }
                    val = sanitizeList((List<?>) val, depth + 1);
                } else {
                    val = sanitizeValue(val, depth + 1);
                }
            } else {
                if (!SAFE_FIELD.matcher(key).matches()) {
                    throw new IllegalArgumentException("Invalid nested field: " + key);
                }
                val = sanitizeValue(val, depth + 1);
            }
            doc.append(key, val);
        }
        return doc;
    }

    private String sanitizeRegex(Object value) {
        if (!(value instanceof String)) {
            throw new IllegalArgumentException("$regex value must be string");
        }
        String pattern = (String) value;
        if (pattern.length() > 100) {
            throw new IllegalArgumentException("Regex too long");
        }
        // Ensure regex doesn't use catastrophic backtracking patterns
        if (pattern.contains("(") && pattern.contains("+") && pattern.contains("*")) {
            throw new IllegalArgumentException("Potentially dangerous regex");
        }
        return pattern;
    }

    // Aggregation search with caching
    public List<Document> aggregateSearch(String collection, Map<String, Object> matchStage,
                                           Map<String, Object> groupBy, String callerRole) {
        String cacheKey = buildCacheKey(collection, matchStage, groupBy, callerRole);

        // Check cache first
        List<Document> cached = queryCache.get(cacheKey);
        if (cached != null) {
            return cached;
        }

        MongoCollection<Document> coll = database.getCollection(sanitizeCollectionName(collection));

        List<Document> pipeline = new ArrayList<>();

        // Build match stage
        Document matchDoc = buildQuery(matchStage, callerRole);
        pipeline.add(new Document("$match", matchDoc));

        // Build group stage
        if (groupBy != null && !groupBy.isEmpty()) {
            Document groupDoc = buildGroupStage(groupBy);
            pipeline.add(groupDoc);
        }

        // Add result limit
        pipeline.add(new Document("$limit", 1000));

        List<Document> results = coll.aggregate(pipeline).into(new ArrayList<>());
        queryCache.put(cacheKey, results);
        return results;
    }

    private Document buildGroupStage(Map<String, Object> groupBy) {
        Document groupDoc = new Document();
        Document idDoc = new Document();

        for (Map.Entry<String, Object> entry : groupBy.entrySet()) {
            String alias = entry.getKey();
            Object fieldSpec = entry.getValue();

            if (!SAFE_FIELD.matcher(alias).matches()) {
                throw new IllegalArgumentException("Invalid group alias: " + alias);
            }

            if (fieldSpec instanceof String) {
                String fieldRef = (String) fieldSpec;
                if (!fieldRef.startsWith("$")) {
                    fieldRef = "$" + fieldRef;
                }
                // Validate the field reference
                String fieldName = fieldRef.substring(1);
                if (!SAFE_FIELD.matcher(fieldName).matches()) {
                    throw new IllegalArgumentException("Invalid group field: " + fieldName);
                }
                idDoc.append(alias, fieldRef);
            } else {
                throw new IllegalArgumentException("Group field must be string reference");
            }
        }

        groupDoc.append("$group", new Document("_id", idDoc)
                .append("count", new Document("$sum", 1)));
        return groupDoc;
    }

    // Text search with scoring
    public List<Document> textSearch(String collection, String searchText,
                                      Map<String, Object> additionalFilters, String callerRole) {
        if (searchText == null || searchText.trim().isEmpty()) {
            throw new IllegalArgumentException("Search text required");
        }
        if (searchText.length() > 500) {
            throw new IllegalArgumentException("Search text too long");
        }

        MongoCollection<Document> coll = database.getCollection(sanitizeCollectionName(collection));

        Document query = new Document();
        query.append("$text", new Document("$search", searchText));

        // Merge additional filters
        if (additionalFilters != null) {
            Document additional = buildQuery(additionalFilters, callerRole);
            query.putAll(additional);
        }

        Document projection = buildProjection(callerRole);
        projection.append("score", new Document("$meta", "textScore"));

        return coll.find(query)
                   .projection(projection)
                   .sort(new Document("score", new Document("$meta", "textScore")))
                   .limit(100)
                   .into(new ArrayList<>());
    }

    // Lookup related documents
    public Document getWithRelated(String collection, String documentId,
                                    List<String> relatedCollections, String callerRole) {
        MongoCollection<Document> coll = database.getCollection(sanitizeCollectionName(collection));

        Document doc = coll.find(Filters.eq("_id", documentId)).first();
        if (doc == null) {
            return null;
        }

        // Check visibility
        if (!"admin".equals(callerRole)) {
            String visibility = doc.getString("visibility");
            if (!"public".equals(visibility)) {
                return null;
            }
        }

        // Fetch related documents
        if (relatedCollections != null) {
            for (String relColl : relatedCollections) {
                String safeColl = sanitizeCollectionName(relColl);
                List<Document> related = database.getCollection(safeColl)
                    .find(Filters.eq("parentId", documentId))
                    .limit(50)
                    .into(new ArrayList<>());
                doc.append("related_" + safeColl, related);
            }
        }

        return doc;
    }

    // Bulk update with field-level access control
    public long bulkUpdate(String collection, Map<String, Object> filter,
                           Map<String, Object> updates, String callerRole) {
        if (!"admin".equals(callerRole) && !"editor".equals(callerRole)) {
            throw new SecurityException("Insufficient permissions for bulk update");
        }

        MongoCollection<Document> coll = database.getCollection(sanitizeCollectionName(collection));

        Document queryFilter = buildQuery(filter, callerRole);
        Document updateDoc = buildUpdateDocument(updates, callerRole);

        return coll.updateMany(queryFilter, updateDoc).getModifiedCount();
    }

    private Document buildUpdateDocument(Map<String, Object> updates, String callerRole) {
        Document setDoc = new Document();
        Set<String> protectedFields = Set.of("_id", "createdBy", "createdAt", "visibility", "owner");

        for (Map.Entry<String, Object> entry : updates.entrySet()) {
            String field = entry.getKey();
            Object value = entry.getValue();

            if (!SAFE_FIELD.matcher(field).matches()) {
                throw new IllegalArgumentException("Invalid update field: " + field);
            }

            if (protectedFields.contains(field) && !"admin".equals(callerRole)) {
                throw new SecurityException("Cannot modify protected field: " + field);
            }

            // Only allow scalar updates
            if (value instanceof String || value instanceof Number ||
                value instanceof Boolean || value == null) {
                setDoc.append(field, value instanceof String ? sanitizeStringValue((String) value) : value);
            } else {
                throw new IllegalArgumentException("Update values must be scalar");
            }
        }

        return new Document("$set", setDoc);
    }

    private Document buildProjection(String callerRole) {
        Document projection = new Document();
        if (!"admin".equals(callerRole)) {
            // Hide internal fields from non-admin users
            projection.append("internalNotes", 0);
            projection.append("auditLog", 0);
            projection.append("accessControl", 0);
        }
        return projection;
    }

    private String sanitizeCollectionName(String name) {
        if (name == null || !SAFE_FIELD.matcher(name).matches()) {
            throw new IllegalArgumentException("Invalid collection name");
        }
        if (name.startsWith("system.")) {
            throw new IllegalArgumentException("Cannot access system collections");
        }
        return name;
    }

    private void validatePagination(int page, int pageSize) {
        if (page < 0 || page > 10000) {
            throw new IllegalArgumentException("Invalid page number");
        }
        if (pageSize < 1 || pageSize > 100) {
            throw new IllegalArgumentException("Invalid page size");
        }
    }

    private String buildCacheKey(String collection, Map<String, Object> match,
                                  Map<String, Object> group, String role) {
        return collection + ":" + Objects.hashCode(match) + ":" +
               Objects.hashCode(group) + ":" + role;
    }

    // Inner class for LRU cache
    private static class QueryCache {
        private final LinkedHashMap<String, List<Document>> cache;

        QueryCache(int maxSize) {
            this.cache = new LinkedHashMap<String, List<Document>>(maxSize, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, List<Document>> eldest) {
                    return size() > maxSize;
                }
            };
        }

        synchronized List<Document> get(String key) {
            return cache.get(key);
        }

        synchronized void put(String key, List<Document> value) {
            cache.put(key, value);
        }
    }
}
